function verifierAdresse(prenom, nom, emailSaisi) {
  const bonneAdresse = prenom + "." + nom + "@univ-lyon2.fr";
  let ok = emailSaisi.length === bonneAdresse.length;
  if (ok) {
    for (let i = 0; i < bonneAdresse.length; i++) {
      if (emailSaisi.charAt(i) !== bonneAdresse.charAt(i)) ok = false;
    }
  }
  return ok;
}

console.log(verifierAdresse("robert", "martin", "robert.martin@univ-lyon2.fr")); // true
console.log(verifierAdresse("robert", "martin", "robert.martin@gmail.com"));     // false

