  var adr = 1;
  var nTaille = chaineMail.length;
  if (nTaille == goodEMail.length) {
    for (i = 0; i < nTaille; i++)
      if (chaineMail.charAt(i) != goodEMail.charAt(i)) {
        adr = 0;
      }
  } else {
    adr = 0;
  }
  if (adr == 1) {
    alert("L'adresse est bonne ! " + chaineMail);
  } else {
    alert("Adresse e-mail invalide !");
  }
}

